import { importEdge, irSchemaViolations, makeCall, useScratchWorkspace } from "@aburi/test-support"
import { describe, expect, it } from "vitest"
import { opensAsGenerated } from "../../src/scan/generated-files"
import { oneSymbolPerFile, scanStubs, stubEffectsPlugin } from "../fixtures/plugins"

describe("opensAsGenerated", () => {
  it.each([
    ["the @generated tag", "// @generated by protobuf-ts 2.9.1\nexport const a = 1\n"],
    [
      "a registry's autogenerated header behind other comments",
      "// @ts-nocheck\n// This file is autogenerated by scripts/build-registry.mts\n// Do not edit this file directly.\nimport * as React from 'react'\n",
    ],
    [
      "Go's convention",
      "// Code generated by protoc-gen-ts_proto. DO NOT EDIT.\r\nexport const a = 1\r\n",
    ],
    [
      "a file said to be auto-generated in a block comment",
      "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\nexport interface paths {}\n",
    ],
    [
      "code said to be automatically generated, after another block",
      "/* eslint-disable */\n/**\n * Generated `api` utility.\n *\n * THIS CODE IS AUTOMATICALLY GENERATED.\n */\nexport const api = {}\n",
    ],
    [
      "generated beside do not edit",
      "/**\n * Generated by orval v6.31.0\n * Do not edit manually.\n */\nexport const getUsers = () => {}\n",
    ],
    [
      "a header behind a shebang",
      "#!/usr/bin/env node\n// This file was generated by kysely-codegen. Please do not edit it manually.\n",
    ],
    ["a byte-order mark before the tag", "﻿// @generated\nexport {}\n"],
    ["a block comment that never closes", "/* @generated"],
    [
      "Thrift's header, its two halves on separate lines of one run",
      "//\n// Autogenerated by Thrift Compiler (0.19.0)\n//\n// DO NOT EDIT UNLESS YOU ARE SURE THAT YOU KNOW WHAT YOU ARE DOING\n//\n",
    ],
    ["a file that says it is an autogenerated file", "// THIS IS AN AUTOGENERATED FILE.\n"],
    [
      "an autogenerated file beside do not edit",
      "/* Autogenerated file. Do not edit manually. */\n",
    ],
    [
      "a phrase across the lines of a block",
      "/**\n * This file was\n * automatically generated by foo.\n */\nexport {}\n",
    ],
    ["a file that has been generated", "// This file has been generated by a script.\n"],
    ["a file that is auto generated", "// This file is auto generated.\n"],
    ["generated by beside do not modify", "// Code generated by sqlc. DO NOT MODIFY.\n"],
    ["generated by beside don't edit", "// Generated by a script; don't edit.\n"],
    [
      "generated by beside a typographic don’t modify",
      "/* Generated by a script. Don’t modify. */\n",
    ],
    ["a header in a file with carriage-return line endings", "// @generated\rexport const a = 1\r"],
  ])("is true for %s", (_case, content) => {
    expect(opensAsGenerated(content)).toBe(true)
  })

  it.each([
    ["a marker after the first code", "import x from 'y'\n// @generated\n"],
    [
      "the first declaration's doc comment describing a value",
      "/** Returns an auto-generated id. */\nexport function newId() {}\n",
    ],
    ["a marker in a string", 'export const banner = "// @generated"\n'],
    ["generated without do not edit", "// Generated documentation lives in docs/.\nexport {}\n"],
    ["do not edit without generated", "// Do not edit without a review.\nexport {}\n"],
    ["a tag that is another word", "// @generatedBy the platform team\nexport {}\n"],
    ["a tag that is a package path", "// Types come from @generated/prisma\nexport {}\n"],
    ["a tag in another case", "// @GENERATED\nexport {}\n"],
    [
      "do not edit and generated in two comments",
      "// Do not edit without running the tests.\n/** Returns the generated slug. */\nexport function slug() {}\n",
    ],
    [
      "do not edit beside a generated that opens no header",
      "// Copyright Acme\n/**\n * Do not edit the returned map; its ids are generated lazily.\n */\nexport function ids() {}\n",
    ],
    [
      "do not edit in a licence header, and a doc comment that opens with generated",
      "// Copyright Acme. Do not edit without approval.\n\n/**\n * Generated ids, one per row.\n */\nexport const ids = []\n",
    ],
    [
      "a generator script describing the file it writes",
      "/** Writes src/registry.ts. The file is generated from the components folder. */\nexport function build() {}\n",
    ],
    [
      "a header past the end of a line comment in a file with carriage-return line endings",
      "// helpers\rexport const tag = '@generated'\r",
    ],
    [
      "a header past the end of a line comment at a line separator",
      "// helpers\u2028export const tag = '@generated'\n",
    ],
    ["an empty file", ""],
  ])("is false for %s", (_case, content) => {
    expect(opensAsGenerated(content)).toBe(false)
  })
})

const workspace = useScratchWorkspace("generated-files")

/** Every Symbol calls itself, which resolves, and `nowhere`, which does not. */
const callingLanguage = oneSymbolPerFile({
  walkBody: (symbol) => ({
    rules: [],
    calls: [makeCall({ target: symbol.name, line: 1 }), makeCall({ target: "nowhere", line: 2 })],
  }),
})

describe("scan — the Symbols of generated files", () => {
  it("carry inGeneratedFile, dropped ones too, and the census counts their calls apart", async () => {
    await workspace.writeSource("src/order.stub", "order")
    await workspace.writeSource("src/client.stub", "// Code generated by codegen. DO NOT EDIT.\n")
    await workspace.writeSource("src/registry.stub", "// @generated\n")
    const language = oneSymbolPerFile({
      walkBody: callingLanguage.walkBody,
      symbolDropHint: (symbol) =>
        symbol.source.file === "src/registry.stub" ? { reason: "stub", category: "B" } : null,
    })

    const { ir } = await scanStubs(workspace.root, { languages: [language] })

    expect(ir.symbols.map((s) => [s.source.file, s.dropped, s.inGeneratedFile])).toEqual([
      ["src/client.stub", false, true],
      ["src/order.stub", false, undefined],
      ["src/registry.stub", true, true],
    ])
    expect(ir.stats.callResolution).toEqual({
      totalCalls: 4,
      resolvedCalls: 2,
      unresolved: { localScope: 0, external: 0, dynamic: 0, ambiguous: 0, noMatch: 2 },
      generated: {
        totalCalls: 2,
        resolvedCalls: 1,
        unresolved: { localScope: 0, external: 0, dynamic: 0, ambiguous: 0, noMatch: 1 },
      },
    })
    expect(irSchemaViolations(ir)).toEqual([])
  })

  it("leave an authored call into them resolved, and the effect it reaches propagated", async () => {
    await workspace.writeSource("src/order.stub", "order")
    await workspace.writeSource("src/client.stub", "// @generated\n")
    const language = oneSymbolPerFile({
      parseFile: async (file) => ({
        tree: {},
        errors: [],
        imports:
          file.path === "src/order.stub"
            ? [importEdge({ source: "./client.stub", symbols: ["src_client_stub"] })]
            : [],
      }),
      walkBody: (symbol) => ({
        rules: [],
        calls: [
          makeCall({
            target: symbol.source.file === "src/order.stub" ? "src_client_stub" : "db.save",
            line: 1,
          }),
        ],
      }),
    })
    const writes = stubEffectsPlugin("effects-db", (call) =>
      call.target === "db.save"
        ? { effectId: "db.write", confidence: "high", derivedBy: "effects-db:save" }
        : null,
    )

    const { ir } = await scanStubs(workspace.root, { languages: [language], effects: [writes] })

    expect(ir.symbols.map((symbol) => [symbol.source.file, symbol.inGeneratedFile])).toEqual([
      ["src/client.stub", true],
      ["src/order.stub", undefined],
    ])
    const order = ir.symbols.find((symbol) => symbol.source.file === "src/order.stub")
    expect(order?.calls.map((call) => call.resolved)).toEqual([
      "stub:src/client.stub#src_client_stub",
    ])
    expect(order?.effects.map((effect) => [effect.id, effect.propagated])).toEqual([
      ["db.write", true],
    ])
  })

  it("leave the census without a generated block when no file is generated", async () => {
    await workspace.writeSource("src/order.stub", "// Generated documentation lives in docs/.\n")

    const { ir } = await scanStubs(workspace.root, { languages: [callingLanguage] })

    expect(ir.symbols.map((s) => "inGeneratedFile" in s)).toEqual([false])
    expect(ir.stats.callResolution).not.toHaveProperty("generated")
  })
})
